// `guitest services`: the engine services (Sim/Script/GMarshal.cs, GUI/Services) printing the same cases as
// tools/parity/godot_services.gd, line for line -- tools/parity/services.sh diffs the two. `guitest services-gen`
// first writes what Godot reads back ($FB_SERVICES_OUT/cs_blobs.txt: this side's compressed data; cs/cfg.cfg).
// Godot-made bytes (var_to_bytes and compressed data) are embedded below (GODOT DATA, regenerated by
// `services.sh --regen`), so the C# decoders are checked on Godot's own output.
// Float literals go through GStr.ToFloat: GDScript parses its literals with Godot's strtod, not a correctly rounded one.
using System;
using System.Collections.Generic;
using System.Linq;
using Fatebound.GUI;
using Fatebound.Sim;

namespace GuiTest
{
    public static partial class ServicesTest
    {
        static string Out = "/tmp/fb-services";
        const string Me = "cs";

        static void p(string k, Var v) => Console.WriteLine(k + "|" + GD.Str(v));
        static double F(string s) => GStr.ToFloat(s);
        static string Esc(string s) => GStr.CEscape(s);
        static Var V(object o) => Var.Of(o);
        static GArray A(params Var[] x) => GArray.Of(x);

        static string Sha(byte[] b)
        {
            var h = new HashingContext();
            h.Start(HashingContext.HASH_SHA256);
            if (b.Length > 0) h.Update(b);
            return h.Finish().HexEncode();
        }

        static byte[] Noise(int n, long seed)
        {
            var b = new byte[n];
            long x = seed;
            for (int i = 0; i < n; i++)
            {
                x = (x * 1103515245 + 12345) & 0x7fffffff;
                b[i] = (byte)((x >> 16) & 255);
            }
            return b;
        }

        static GDict ProtoMsg() => new GDict {
            { "t", "snap" }, { "tick", 123456 }, { "you", 3 }, { "dt", F("0.05") }, { "u", V(new byte[] { 1, 2, 3, 4, 5, 6, 7 }) },
            { "h", A(A(1, 2, 300000), A(4, -5, 6)) }, { "p", new GDict { { "x", F("1.25") }, { "y", F("-7.5") }, { "name", "Kévin" } } } };

        static GValue GV(int type, params double[] c) => new GValue(type, c);

