                ("f0", Math.Abs(negz)), ("fneg0", negz), ("f1", F("1.0")), ("fhalf", F("0.5")), ("f01", F("0.1")), ("fthird", F("1.0") / F("3.0")), ("f1e20", F("1e20")),
