                ("f123", F("123.456")), ("f1e5", F("1e-5")), ("f15e7", F("1.5e-7")), ("f1e15", F("1e15")), ("f1e16", F("1e16")), ("fm25", -F("2.5")), ("f3", F("3.0")), ("f16m", F("16777217.0")),
                ("s0", ""), ("s1", "a"), ("s3", "abc"), ("s4", "abcd"), ("s5", "abcde"), ("sutf", "héllo wörld"), ("sjp", "日本語"), ("semoji", "😀x"),
