                    { 5, "five" }, { F("2.5"), "f" }, { new Vec2i(1, 2), new GArray() }, { true, false } }),
                ("anest", A(A(1, A(2, A(3, new GArray()))), new GDict(), A(new GDict { { "k", V(new byte[] { 7 }) } }))),
                ("proto", ProtoMsg()),
                ("dkeys", new GDict { { "b", 1 }, { "a", 2 }, { 10, 3 }, { 2, 4 }, { F("1.5"), 5 }, { new Vec2(1, 0), 6 }, { "B", 7 }, { "é", 8 }, { -1, 9 }, { "", 10 },
                    { false, 12 }, { F("2.0"), 13 } }),
            };
        }

        static readonly string[] NoStr = { "col", "col2", "pcol", "r2", "t2d" };

        /// <summary>typeof() as Godot gives it, for the GUI's registered value types too (Col is Color...).</summary>
        static int TypeOf(Var v)
        {
            var o = v.Obj;
            if (v.IsObj && GMarshal.TryComponents(o, out int t, out _)) return t;
            if (o is Array arr && !(o is byte[]) && arr.GetType().GetElementType().IsValueType)
            {
                var et = arr.GetType().GetElementType();
                object sample = arr.Length > 0 ? arr.GetValue(0) : Activator.CreateInstance(et);
                if (GMarshal.TryComponents(sample, out int st, out _))
                    return st == GD.TYPE_COLOR ? GD.TYPE_PACKED_COLOR_ARRAY : GD.TYPE_PACKED_VECTOR4_ARRAY;
            }
            if (o is GValue[] ga) return ga.Length > 0 && ga[0].Type == GD.TYPE_VECTOR4 ? GD.TYPE_PACKED_VECTOR4_ARRAY : GD.TYPE_PACKED_COLOR_ARRAY;
            return v.GodotType;
        }

        static byte[] Hex(string h) => GStr.HexDecode(h);

        public static void Run(bool genOnly)
        {
            string o = System.Environment.GetEnvironmentVariable("FB_SERVICES_OUT");
            if (!string.IsNullOrEmpty(o)) Out = o;
            PlatformHost.Init(new DefaultPlatform(Out + "/user"));
            DirAccess.MakeDirRecursiveAbsolute(Out + "/" + Me);
            if (genOnly)
            {
                Gen();
                return;
            }
            MarshalCases();
            CompressionCases();
            BytesCases();
            Base64HashCases();
            TimeCases();
            TextCases();
            ConfigCases();
            FileCases();
            RegexCases();
            MiscCases();
            ThreadCases();
            LoggerCases();
            WsCases();
            HttpCases();
        }

        // what Godot reads from this side
        static void Gen()
        {
            using (var f = FileAccess.Open(Out + "/cs_blobs.txt", FileAccess.WRITE))
                foreach (int mode in new[] { FileAccess.COMPRESSION_DEFLATE, FileAccess.COMPRESSION_ZSTD, FileAccess.COMPRESSION_GZIP })
                    foreach (var (name, src) in CompInputs())
                        f.StoreLine(mode + "|" + name + "|" + src.Compress(mode).HexEncode());
            CfgBuild().Save(Out + "/" + Me + "/cfg.cfg");
        }

        // ---------------------------------------------------------------- var_to_bytes / bytes_to_var / var_to_str
        static void MarshalCases()
        {
            foreach (var (name, v) in Values())
            {
                var b = GD.VarToBytes(v);
                p("vb|" + name, b.HexEncode());
                p("vs|" + name, Esc(GD.VarToStr(v)));
                var back = GD.BytesToVar(Hex(GodotBytes[name]));       // Godot's bytes
                p("rt|" + name, Esc(GD.VarToStr(back)));
                p("ty|" + name, TypeOf(back));
                if (!NoStr.Contains(name)) p("st|" + name, Esc(GD.Str(back)));
                p("rs|" + name, Esc(GD.VarToStr(GD.StrToVar(GD.VarToStr(v)))));
            }
            p("bad1", GD.BytesToVar(new byte[] { 1, 0, 0 }));
            p("bad2", GD.BytesToVar(new byte[] { 4, 0, 0, 0, 9, 0, 0, 0, 65 }));
            p("bad3", GD.BytesToVar(new byte[] { 99, 0, 0, 0 }));
            p("bad4", GD.BytesToVar(new byte[] { 24, 0, 0, 0, 0, 0, 0, 0 }));
            foreach (var name in new[] { "strname", "nodepath", "nodepath2", "typedarr", "typedarr_s", "objarr", "typeddict", "typeddict_vt" })
            {
                p("gvb|" + name, GodotOnly[name]);
                p("grt|" + name, Esc(GD.Str(GD.BytesToVar(Hex(GodotOnly[name])))));
            }
            var hand = new[] { "05000100000000000000f83f00000000000000c0", "07000100000000000000f03f00000000000000400000000000000c400000000000001040",
                "23000100010000000000000000f83f00000000000000c0", "140001000000803f0000003f0000803e0000803f", "1d00000003000000010203",
                "0400000002000000fffe0000", "0400000005000000efbbbf4142000000", "040000000300000041004200", "1c000000ffffff7f", "02000000ff",
                "1b0000000100000002000000", "09000100000000000000f03f00000000000000400000000000000840", "220000000100000002000000414200000",
                "2200000001000000020000004142000000", "1c00010063000000000000000", "1c0001006300000000000000", "020001000100000000000000",
                "0e000100000000000000000000000000000000000000000000f03f0000000000000440", "25000000010000000000803f0000003f0000803e" };
            foreach (var h in hand)
            {
                Var hv = h.Length % 2 == 0 ? GD.BytesToVar(Hex(h)) : Var.Nil;
                p("hand|" + h, GD.Fmt("%d|%s", TypeOf(hv), Esc(GD.VarToStr(hv))));
            }
            p("callable", GD.VarToBytes((Action)(() => { })).HexEncode());
            foreach (var v in new[] { double.NaN, 1.0 / double.NegativeInfinity, F("0.30000000000000004"), F("1e100"), F("123456789.0"), F("0.000123"), F("1e-4"), F("2.5e-5"), F("1e22"),
                F("5e-324"), F("4.9e-324") * 3, F("0.1") + F("0.7"), F("100.0"), F("1234567890123456.0"), F("12345678901234567.0") })
                p("vstr", GD.VarToStr(v));
        }

        // ---------------------------------------------------------------- compression
        static List<(string, byte[])> CompInputs()
        {
            var text = new System.Text.StringBuilder();
            for (int i = 0; i < 200; i++) text.Append(GD.Fmt("Fatebound siege %d; ", i));
            return new List<(string, byte[])> { ("hello", "hello".ToUtf8Buffer()), ("text", text.ToString().ToUtf8Buffer()), ("proto", GD.VarToBytes(ProtoMsg())),
                ("noise", Noise(3000, 7)), ("one", new byte[] { 42 }) };
        }

        static void CompressionCases()
        {
            var csBlobs = new Dictionary<string, byte[]>();
            var f = FileAccess.Open(Out + "/cs_blobs.txt", FileAccess.READ);
            if (f != null)
                using (f)
                    while (!f.EofReached())
                    {
                        string l = f.GetLine();
                        if (l.Length == 0) continue;
                        var parts = l.Split('|');
                        csBlobs[parts[0] + "|" + parts[1]] = Hex(parts[2]);
                    }
            foreach (int mode in new[] { FileAccess.COMPRESSION_DEFLATE, FileAccess.COMPRESSION_ZSTD, FileAccess.COMPRESSION_GZIP })
            {
                p("empty|" + mode, new byte[0].Compress(mode).Length);
                foreach (var (name, src) in CompInputs())
                {
                    string key = mode + "|" + name;
                    var z = Hex(GodotZ[key]);                      // Godot's compressed bytes
                    p("gz|" + key, z.HexEncode());
                    var d = z.Decompress(src.Length, mode);
                    p("gd|" + key, d.Length + "|" + Sha(d));
                    p("gbig|" + key, z.Decompress(src.Length + 100, mode).Length);
                    p("gsmall|" + key, z.Decompress(Math.Max(1, src.Length - 1), mode).Length);
                    if (mode != FileAccess.COMPRESSION_ZSTD)
                    {
                        var dd = z.DecompressDynamic(-1, mode);
                        p("gdyn|" + key, dd.Length + "|" + Sha(dd));
                        p("gdynlim|" + key, z.DecompressDynamic(src.Length - 1, mode).Length);
                    }
                    var cz = csBlobs.TryGetValue(key, out var bz) ? bz : new byte[0];
                    var cd = cz.Length > 0 ? cz.Decompress(src.Length, mode) : new byte[0];
                    p("cs|" + key, cd.Length + "|" + Sha(cd));
                    if (mode != FileAccess.COMPRESSION_ZSTD && cz.Length > 0)
                    {
                        var cdd = cz.DecompressDynamic(-1, mode);
                        p("csdyn|" + key, cdd.Length + "|" + Sha(cdd));
                    }
                }
            }
            var raw = GD.VarToBytes(ProtoMsg());
            var frame = new byte[5];
            frame[0] = 0x5A;
            frame.EncodeU32(1, raw.Length);
            frame = frame.Concat(raw.Compress(FileAccess.COMPRESSION_ZSTD)).ToArray();
            long n = frame.DecodeU32(1);
            p("zframe", Esc(GD.VarToStr(GD.BytesToVar(frame.Slice(5).Decompress(n, FileAccess.COMPRESSION_ZSTD)))));
            p("badz", new byte[] { 1, 2, 3, 4, 5, 6, 7, 8 }.Decompress(100, FileAccess.COMPRESSION_ZSTD).Length);
            p("badgz", new byte[] { 31, 139, 8, 0, 1, 2, 3 }.DecompressDynamic(-1, FileAccess.COMPRESSION_GZIP).Length);
        }

        // ---------------------------------------------------------------- PackedByteArray encode_* / decode_*
        static void BytesCases()
        {
            var b = new byte[48];
            b.EncodeU8(0, 255);
            b.EncodeS8(1, -2);
            b.EncodeU16(2, 65535);
            b.EncodeS16(4, -300);
            b.EncodeU32(6, 4000000000);
            b.EncodeS32(10, -5);
            b.EncodeU64(14, -1);
            b.EncodeS64(22, -123456789012);
            b.EncodeFloat(30, F("0.1"));
            b.EncodeHalf(34, F("1.5"));
            b.EncodeDouble(36, F("2.5"));
            b.EncodeS16(44, 40000);
            b.EncodeU8(46, -1);
            b.EncodeU8(47, 256);
            b.EncodeU32(46, 1);
            p("enc", b.HexEncode());
            p("dec", A(b.DecodeU8(0), b.DecodeS8(1), b.DecodeU16(2), b.DecodeS16(4), b.DecodeU32(6), b.DecodeS32(10), b.DecodeU64(14),
                b.DecodeS64(22), b.DecodeFloat(30), b.DecodeHalf(34), b.DecodeDouble(36), b.DecodeS16(44), b.DecodeU16(44), b.DecodeS8(46)));
            p("dec_oob", A(b.DecodeU32(46), b.DecodeU8(48), b.DecodeS16(-1), b.DecodeDouble(41)));
            var h = new byte[16];
            var hv = new[] { F("0.0"), F("1.0"), -F("2.5"), F("65504.0"), F("70000.0"), F("1e-8"), F("0.333"), F("6.1e-5"), double.NegativeInfinity };
            for (int i = 0; i < hv.Length; i++)
                if (i * 2 < 16) h.EncodeHalf(i * 2, hv[i]);
            p("half", h.HexEncode());
            var hd = new GArray();
            for (int i = 0; i < 8; i++) hd.Append(h.DecodeHalf(i * 2));
            p("halfd", hd);
            var hs = new byte[] { 0x01, 0x00, 0xff, 0x03, 0x00, 0x7c, 0x01, 0x7c };
            p("halfs", A(hs.DecodeHalf(0), hs.DecodeHalf(2), hs.DecodeHalf(4), double.IsNaN(hs.DecodeHalf(6))));
            var vb = new byte[64];
            p("encvar", vb.EncodeVar(4, new GDict { { "a", A(1, 2) } }));
            p("decvar", Esc(GD.VarToStr(vb.DecodeVar(4))));
            p("decvarsize", vb.DecodeVarSize(4));
            p("hasvar", A(vb.HasEncodedVar(4), vb.HasEncodedVar(62), vb.HasEncodedVar(60)));
            p("encvar_nofit", vb.EncodeVar(60, "too long string"));
            var s5 = new byte[] { 1, 2, 3, 4, 5 };
            p("slice", A(s5.Slice(1, 3).HexEncode(), s5.Slice(-2).HexEncode(), s5.Slice(4, 2).HexEncode(), s5.Slice(-10, 10).HexEncode(), s5.Slice(5).HexEncode()));
            p("toarr", A(V(new byte[] { 1, 0, 0, 0, 255, 255, 255, 255 }.ToInt32Array()), V(new byte[] { 0, 0, 128, 63, 1 }.ToFloat32Array()),
                V(new byte[] { 1, 0, 0, 0, 0, 0, 0, 128 }.ToInt64Array()), V(new byte[] { 0, 0, 0, 0, 0, 0, 240, 63 }.ToFloat64Array())));
        }

        // ---------------------------------------------------------------- base64, hashing, crypto
        static void Base64HashCases()
        {
            foreach (var arr in new[] { new byte[] { 0 }, new byte[] { 1, 2 }, new byte[] { 1, 2, 3 }, Noise(100, 3) })
            {
                string s = Marshalls.RawToBase64(arr);
                p("b64", s);
                p("b64back", Marshalls.Base64ToRaw(s).HexEncode());
            }
            p("u8b64", Marshalls.Utf8ToBase64("héllo 😀"));
            p("b64u8", Marshalls.Base64ToUtf8(Marshalls.Utf8ToBase64("héllo 😀")));
            p("u8b64e", Marshalls.Utf8ToBase64(""));
            string vs = Marshalls.VariantToBase64(new GDict { { "a", A(1, F("2.5")) }, { "b", new Vec2(1, 2) } });
            p("vb64", vs);
            p("b64v", Esc(GD.VarToStr(Marshalls.Base64ToVariant(vs))));
            p("b64nl", Marshalls.Base64ToRaw("AQID\nBA==").HexEncode());
            foreach (int t in new[] { HashingContext.HASH_MD5, HashingContext.HASH_SHA1, HashingContext.HASH_SHA256 })
            {
                var h = new HashingContext();
                p("hstart", A(h.Start(t), h.Start(t)));
                h.Update("abc".ToUtf8Buffer());
                p("hempty", h.Update(new byte[0]));
                h.Update(Noise(1000, 5));
                p("hash", h.Finish().HexEncode());
                p("hfin2", h.Finish().Length);
                p("hupd", h.Update(new byte[] { 1 }));
                h.Start(t);
                h.Update("abc".ToUtf8Buffer());
                p("habc", h.Finish().HexEncode());
            }
            var cr = new Crypto();
            p("rand", A(cr.GenerateRandomBytes(10).Length, cr.GenerateRandomBytes(0).Length));
            p("hmac", cr.HmacDigest(HashingContext.HASH_SHA256, "key".ToUtf8Buffer(), "The quick brown fox".ToUtf8Buffer()).HexEncode());
            p("hmac1", cr.HmacDigest(HashingContext.HASH_SHA1, "k".ToUtf8Buffer(), Noise(200, 9)).HexEncode());
            p("ctc", A(cr.ConstantTimeCompare(new byte[] { 1, 2 }, new byte[] { 1, 2 }), cr.ConstantTimeCompare(new byte[] { 1, 2 }, new byte[] { 1, 3 })));
        }

        // ---------------------------------------------------------------- Time
        static void TimeCases()
        {
            var times = new long[] { 0, 1, -1, 59, 86399, 86400, -86400, -86401, 951782400, 951868800, 1709164800, 1709251199, 4102444800, -2208988800,
                -62135596800, -62167219200, -62198755200, 253402300799, 1761500000, 10000000000, -100000000000, 1700000000, -11644473600 };
            foreach (long t in times)
            {
                string k = t.ToString();
                p("td|" + k, Time.GetDatetimeDictFromUnixTime(t));
                p("tdd|" + k, Time.GetDateDictFromUnixTime(t));
                p("ttd|" + k, Time.GetTimeDictFromUnixTime(t));
                p("ts|" + k, Time.GetDatetimeStringFromUnixTime(t));
                p("tss|" + k, Time.GetDatetimeStringFromUnixTime(t, true));
                p("tds|" + k, Time.GetDateStringFromUnixTime(t));
                p("tts|" + k, Time.GetTimeStringFromUnixTime(t));
                var d = Time.GetDatetimeDictFromUnixTime(t);
                p("tback|" + k, Time.GetUnixTimeFromDatetimeDict(d));
                p("tbacks|" + k, Time.GetUnixTimeFromDatetimeString(Time.GetDatetimeStringFromUnixTime(t)));
            }
            p("tfloat", A(Time.GetDatetimeDictFromUnixTime(F("1700000000.9")), Time.GetDatetimeStringFromUnixTime(-F("1.5"))));
            foreach (var s in new[] { "2024-02-29T12:34:56", "2024-02-29 12:34:56", "1999-12-31", "23:59:58", "-0005-03-01 01:02:03", "2023-02-29T00:00:00", "2020-13-01T00:00:00", "1970-01-01T00:00:60", "abc" })
                p("tstr|" + s, A(Time.GetDatetimeDictFromDatetimeString(s, true), Time.GetDatetimeDictFromDatetimeString(s, false), Time.GetUnixTimeFromDatetimeString(s)));
            p("tdictstr", A(Time.GetDatetimeStringFromDatetimeDict(new GDict { { "year", 2020 }, { "month", 5 }, { "day", 6 }, { "hour", 7 } }, false),
                Time.GetDatetimeStringFromDatetimeDict(new GDict { { "year", 2020 }, { "month", 5 }, { "day", 6 }, { "hour", 7 } }, true),
                Time.GetDatetimeStringFromDatetimeDict(new GDict(), false), Time.GetDatetimeStringFromDatetimeDict(new GDict { { "month", 2 }, { "day", 30 } }, false),
                Time.GetUnixTimeFromDatetimeDict(new GDict { { "year", 2000 } }), Time.GetUnixTimeFromDatetimeDict(new GDict { { "day", 0 } })));
            p("toff", A(Time.GetOffsetStringFromOffsetMinutes(-420), Time.GetOffsetStringFromOffsetMinutes(330), Time.GetOffsetStringFromOffsetMinutes(0), Time.GetOffsetStringFromOffsetMinutes(-61)));
            var sys = Time.GetDatetimeDictFromSystem();
            p("sysk", sys.Keys());
            var types = new GArray();
            foreach (var key in sys) types.Append(GD.TypeOf(sys[key]));
            p("syst", types);
            p("sysk2", A(Time.GetDateDictFromSystem().Keys(), Time.GetTimeDictFromSystem(true).Keys(), Time.GetDatetimeDictFromSystem(true)["dst"]));
            p("sysdst", sys["dst"]);
            var utc = Time.GetDatetimeDictFromSystem(true);
            var loc = Time.GetDatetimeDictFromSystem();
            long u = (long)Time.GetUnixTimeFromSystem();
            p("offmin", GD.Roundi((Time.GetUnixTimeFromDatetimeDict(loc) - Time.GetUnixTimeFromDatetimeDict(utc)) / 60.0));
