        static void CfgDump(string tag, ConfigFile c)
        {
            p(tag + "|text", Esc(c.EncodeToText()));
            p(tag + "|secs", V(c.GetSections()));
            foreach (var s in c.GetSections())
            {
                var kv = new GArray();
                foreach (var k in c.GetSectionKeys(s)) kv.Append(k + "=" + GD.VarToStr(c.GetValue(s, k)));
                p(tag + "|sec|" + s, Esc(GD.Str(kv)));
            }
        }

