        // ---------------------------------------------------------------- WebSocketPeer (against a Godot ws_server.gd: $FB_WS_URL)
        static void WsPoll(WebSocketPeer ws)
        {
            ws.Poll();
            System.Threading.Thread.Sleep(2);
        }

        static int WsWaitState(WebSocketPeer ws, int want)
        {
            long t0 = Time.GetTicksMsec();
            while (ws.GetReadyState() != want && Time.GetTicksMsec() - t0 < 5000) WsPoll(ws);
            return ws.GetReadyState();
        }

        static byte[] WsWaitPacket(WebSocketPeer ws)
        {
            long t0 = Time.GetTicksMsec();
            while (ws.GetAvailablePacketCount() == 0 && Time.GetTicksMsec() - t0 < 5000) WsPoll(ws);
            return ws.GetPacket();
        }

        static void WsCases()
        {
            string url = System.Environment.GetEnvironmentVariable("FB_WS_URL");
            if (string.IsNullOrEmpty(url)) { p("ws", "skipped (no FB_WS_URL)"); return; }
            var ws = new WebSocketPeer();
            ws.OutboundBufferSize = 1 << 17;
            p("ws_state0", A(ws.GetReadyState(), ws.GetCloseCode(), ws.GetAvailablePacketCount()));
            p("ws_connect", ws.ConnectToUrl(url));
            p("ws_connecting", ws.GetReadyState());
            p("ws_again", ws.ConnectToUrl(url));
            p("ws_open", WsWaitState(ws, WebSocketPeer.STATE_OPEN));
            p("ws_proto", ws.GetSelectedProtocol());
            p("ws_put", ws.PutPacket(GD.VarToBytes(new GDict { { "t", "hi" }, { "n", 1 }, { "v", new Vec2(1, 2) }, { "s", "héllo" } })));
            var pkt = WsWaitPacket(ws);
            p("ws_echo1", A(Esc(GD.VarToStr(GD.BytesToVar(pkt))), ws.WasStringPacket(), ws.GetPacketError()));
            p("ws_text", ws.SendText("hello ws"));
            pkt = WsWaitPacket(ws);
            p("ws_echo2", A(pkt.GetStringFromUtf8(), ws.WasStringPacket()));
            var big = Noise(50000, 11);
            p("ws_big", ws.PutPacket(GD.VarToBytes(V(big))));
            pkt = WsWaitPacket(ws);
            var bigback = GD.BytesToVar(pkt).As<byte[]>() ?? new byte[0];
            p("ws_echo3", A(bigback.Length, Sha(bigback), ws.WasStringPacket()));
            p("ws_none", A(ws.GetAvailablePacketCount(), ws.GetPacket().Length, ws.GetPacketError()));
            p("ws_bye", ws.PutPacket(GD.VarToBytes(new GDict { { "t", "bye" } })));
            var msgs = new GArray();
            long t0 = Time.GetTicksMsec();
            while (ws.GetReadyState() != WebSocketPeer.STATE_CLOSED && Time.GetTicksMsec() - t0 < 5000)
            {
                WsPoll(ws);
                while (ws.GetAvailablePacketCount() > 0) msgs.Append(Esc(GD.VarToStr(GD.BytesToVar(ws.GetPacket()))));
            }
            p("ws_msgs", msgs);
            p("ws_closed", A(ws.GetReadyState(), ws.GetCloseCode(), ws.GetCloseReason(), ws.GetAvailablePacketCount()));
            p("ws_put_closed", ws.PutPacket(new byte[] { 1 }));
            var ws2 = new WebSocketPeer();
            ws2.ConnectToUrl(url);
            p("ws2_open", WsWaitState(ws2, WebSocketPeer.STATE_OPEN));
            ws2.Close(1000, "done");
            p("ws2_closing", ws2.GetReadyState());
            p("ws2_closed", A(WsWaitState(ws2, WebSocketPeer.STATE_CLOSED), ws2.GetCloseCode(), ws2.GetCloseReason()));
            p("ws2_reconnect", ws2.ConnectToUrl(url));
            p("ws2_reopen", A(WsWaitState(ws2, WebSocketPeer.STATE_OPEN), ws2.GetCloseCode()));
            ws2.Close();
            WsWaitState(ws2, WebSocketPeer.STATE_CLOSED);
            var ws3 = new WebSocketPeer();
            ws3.ConnectToUrl("ws://127.0.0.1:1/");
            p("ws3_refused", A(WsWaitState(ws3, WebSocketPeer.STATE_CLOSED), ws3.GetCloseCode()));
            var ws4 = new WebSocketPeer();
            p("ws4_bad", A(ws4.ConnectToUrl("http://127.0.0.1:1/"), ws4.GetReadyState()));
            var ws5 = new WebSocketPeer();
            ws5.ConnectToUrl(url);
            ws5.Close();
            p("ws5_abort", A(ws5.GetReadyState(), ws5.GetCloseCode()));
        }

