        static void HttpCases()
        {
            string baseUrl = System.Environment.GetEnvironmentVariable("FB_HTTP_URL");
            if (string.IsNullOrEmpty(baseUrl)) { p("http", "skipped (no FB_HTTP_URL)"); return; }
            var cases = new[]
            {
                new GDict { { "name", "get" }, { "url", baseUrl + "/a.txt" } },
                new GDict { { "name", "missing" }, { "url", baseUrl + "/missing.txt" } },
                new GDict { { "name", "post" }, { "url", baseUrl + "/a.txt" }, { "method", HTTPClient.METHOD_POST }, { "body", "x=1" }, { "headers", A("Content-Type: application/x-www-form-urlencoded") } },
                new GDict { { "name", "head" }, { "url", baseUrl + "/a.txt" }, { "method", HTTPClient.METHOD_HEAD } },
                new GDict { { "name", "range" }, { "url", baseUrl + "/a.txt" }, { "headers", A("Range: bytes=0-9") } },
                new GDict { { "name", "limit" }, { "url", baseUrl + "/a.txt" }, { "limit", 10 } },
                new GDict { { "name", "download" }, { "url", baseUrl + "/data.bin" }, { "file", Out + "/" + Me + "/dl.bin" } },
                new GDict { { "name", "refused" }, { "url", "http://127.0.0.1:1/x" } },
            };
            var tree = new SceneTree(new Vec2(64, 64));
            var http = new HTTPRequest();
            p("http_notree", http.Request(baseUrl + "/a.txt"));
            tree.Root.AddChild(http);
            int i = -1;
            bool done = false;
            Action next = null;
            http.RequestCompleted += (result, code, headers, body) =>
            {
                var c = cases[i];
                string cl = "";
                foreach (var hdr in headers)
                    if (hdr.ToLowerInvariant().StartsWith("content-length:")) cl = hdr.Substring(15).StripEdges();
                string extra = c.Has("file") ? Sha(FileAccess.GetFileAsBytes(c["file"].S)) : "";
                p("http|" + c["name"].S, A(result, code, body.Length, body.Length > 0 ? Sha(body) : "", cl, extra, headers.Length > 0));
                http.CallDeferred(next);
            };
            next = () =>
            {
                i++;
                if (i >= cases.Length) { done = true; return; }
                var c = cases[i];
                http.BodySizeLimit = c.Get("limit", -1).I;
                http.DownloadFile = c.Get("file", "").S;
                var hs = c.Has("headers") ? c["headers"].A.ToStrings().ToArray() : new string[0];
                int err = http.Request(c["url"].S, hs, c.Get("method", HTTPClient.METHOD_GET).I, c.Get("body", "").S);
                p("http_req|" + c["name"].S, err);
                if (i == 0) p("http_busy", http.Request(c["url"].S));
            };
            next();
            for (int frame = 0; frame < 3000 && !done; frame++)
            {
                tree.Iterate(1.0 / 60.0);
                System.Threading.Thread.Sleep(2);
            }
            if (!done) p("http", "timed out");
        }
    }

